import{_ as t,o as i,c as a,a3 as d,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/reportverwaltung/reports-grundlagen-7.png",b=JSON.parse('{"title":"Die Ordnerstruktur der Reportverwaltung","description":"","frontmatter":{"title":"Die Ordnerstruktur der Reportverwaltung","source_pageid":1571,"source_revision":6684},"headers":[],"relativePath":"reporting/reportverwaltung/die-ordnerstruktur-der-reportverwaltung.md","filePath":"reporting/reportverwaltung/die-ordnerstruktur-der-reportverwaltung.md"}'),l={name:"reporting/reportverwaltung/die-ordnerstruktur-der-reportverwaltung.md"};function o(u,n,p,g,h,c){return i(),a("div",null,[...n[0]||(n[0]=[d('<h1 id="die-ordnerstruktur-der-reportverwaltung" tabindex="-1">Die Ordnerstruktur der Reportverwaltung <a class="header-anchor" href="#die-ordnerstruktur-der-reportverwaltung" aria-label="Permalink to &quot;Die Ordnerstruktur der Reportverwaltung&quot;">​</a></h1><p>Organisieren Sie Ihre Reports in einer Ordnerstruktur, die zu den Arbeitsabläufen Ihrer Schule passt. Die Struktur ist grundsätzlich frei wählbar. Zwei bei der Installation angelegte Ordner haben eine besondere Aufgabe.</p><h2 id="besondere-ordner" tabindex="-1">Besondere Ordner <a class="header-anchor" href="#besondere-ordner" aria-label="Permalink to &quot;Besondere Ordner&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/reports-grundlagen-7.png"><img src="'+s+'" alt="Die Ordnerstruktur im Windows-Explorer." loading="lazy"></a></p><p><em>Die Ordnerstruktur im Windows-Explorer.</em></p><table tabindex="0"><thead><tr><th>Ordner</th><th>Aufgabe</th></tr></thead><tbody><tr><td><code>Subreports</code></td><td>Enthält Unterreports, die andere Reports verwenden können. Häufig benötigte Bestandteile müssen dadurch nicht für jeden Report neu erstellt werden.</td></tr><tr><td><code>Header_Footer</code></td><td>Enthält besondere Subreports für Köpfe und Füße, die über oder unter einer Reportausgabe eingefügt werden.</td></tr></tbody></table><p>Greifen mehrere Reports beim Erzeugen ihrer Ausgabe auf denselben Subreport zu, wirkt sich eine Änderung dieses Subreports auf alle diese Ausgaben aus.</p><h2 id="beispiele-fur-gemeinsam-verwendete-bestandteile" tabindex="-1">Beispiele für gemeinsam verwendete Bestandteile <a class="header-anchor" href="#beispiele-fur-gemeinsam-verwendete-bestandteile" aria-label="Permalink to &quot;Beispiele für gemeinsam verwendete Bestandteile&quot;">​</a></h2><ul><li>Ein allgemeiner Adresskopf kann in mehreren Serienbriefen verwendet werden.</li><li>Ein formaler Kopf eignet sich für externe Briefe, ein platzsparender Kopf für interne Listen.</li><li>Ein gemeinsamer Fuß kann auf allen Klassen- und Kurslisten das Druckdatum ausgeben.</li></ul><h2 id="eigene-ordner-anlegen" tabindex="-1">Eigene Ordner anlegen <a class="header-anchor" href="#eigene-ordner-anlegen" aria-label="Permalink to &quot;Eigene Ordner anlegen&quot;">​</a></h2><p>Wählen Sie für weitere Reports eine für Ihre Schule passende Gliederung, etwa nach Aufgaben oder Schulstufen. Wie Sie einen Report in einem solchen Ordner bereitstellen, zeigt <a href="/reporting/reportverwaltung/reports-in-die-reportverwaltung-einfuegen.html">Reports in die Reportverwaltung einfügen</a>.</p>',11),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),r("Tipp – Zeugnisformulare für Nachdrucke aufbewahren")]),e("p",null,[r("Legen Sie einen Ordner "),e("code",null,"Zeugnisse"),r(" mit Unterordnern für Schuljahr und Halbjahr an. Löschen Sie diese Formulare nach der Zeugnisphase nicht. So können Sie Nachdrucke für einen früheren Lernabschnitt mit den ursprünglich dafür heruntergeladenen Zeugnisformularen erstellen.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Die_Ordnerstruktur_der_Reportverwaltung",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 6684.")],-1)])])}const m=t(l,[["render",o]]);export{b as __pageData,m as default};
